{
"title": "HTTP Latency",
"timeRange": {"from": "now-1h", "to": "now"},
"refreshIntervalMs": 15000,
"panels": [
{
"id": "latency-percentiles",
"title": "Request latency: p50 / p95 / p99",
"viz": "line",
"format": "ms",
"query": {
"sourceId": "eval-demo",
"sql": "SELECT time_bucket('1 minute', ts) AS minute, percentile_cont(0.50) WITHIN GROUP (ORDER BY duration_ms) AS p50, percentile_cont(0.95) WITHIN GROUP (ORDER BY duration_ms) AS p95, percentile_cont(0.99) WITHIN GROUP (ORDER BY duration_ms) AS p99 FROM http_requests GROUP BY minute ORDER BY minute",
"timeField": "minute"
},
"options": {
"unit": "ms",
"legend": "bottom",
"yAxis": {"label": "latency (ms)"}
},
"layout": {"x": 0, "y": 0, "w": 6, "h": 4},
"description": "Per-minute p50, p95 and p99 request latency in milliseconds, computed as percentiles of duration_ms across all HTTP requests grouped into one-minute buckets."
},
{
"id": "slowest-routes-p95",
"title": "Slowest routes by p95 latency",
"viz": "bar",
"format": "ms",
"query": {
"sourceId": "eval-demo",
"sql": "SELECT route, percentile_cont(0.95) WITHIN GROUP (ORDER BY duration_ms) AS p95_ms FROM http_requests GROUP BY route ORDER BY p95_ms DESC LIMIT 10"
},
"options": {
"unit": "ms",
"legend": "none"
},
"layout": {"x": 6, "y": 0, "w": 6, "h": 4},
"description": "Routes ranked by p95 request latency in milliseconds, computed as the 95th percentile of duration_ms per route and limited to the ten slowest."
}
]
}
